def choose_move(observation):
    grid_width = observation.get("grid_width", 0)
    grid_height = observation.get("grid_height", 0)
    self_position = observation.get("self_position", (0, 0))
    opponent_position = observation.get("opponent_position", (0, 0))
    resources = observation.get("resources", [])
    obstacles = observation.get("obstacles", [])
    remaining_resource_count = observation.get("remaining_resource_count", 0)
    scores = observation.get("scores", {})
    self_path = observation.get("self_path", [])
    opponent_path = observation.get("opponent_path", [])

    def clamp(n):
        if n < -1:
            return -1
        if n > 1:
            return 1
        return int(n)

    x, y = self_position

    ox, oy = opponent_position
    if ox == x and oy == y:
        return [0, 0]

    if resources:
        best_r = None
        best_d = None
        for r in resources:
            rx, ry = r.get("position", (0, 0))
            d = abs(rx - x) + abs(ry - y)
            if best_d is None or d < best_d:
                best_d = d
                best_r = (rx, ry)
        if best_r is not None:
            rx, ry = best_r
            return [clamp(rx - x), clamp(ry - y)]

    if obstacles:
        nearest_obs = None
        nearest_d = None
        for o in obstacles:
            ox2, oy2 = o.get("position", (0, 0))
            d = abs(ox2 - x) + abs(oy2 - y)
            if nearest_d is None or d < nearest_d:
                nearest_d = d
                nearest_obs = (ox2, oy2)
        if nearest_obs is not None:
            ox2, oy2 = nearest_obs
            dx = clamp(ox2 - x)
            dy = clamp(oy2 - y)
            if dx != 0 or dy != 0:
                return [dx, dy]

    dx = clamp(ox - x)
    dy = clamp(oy - y)
    if dx != 0 or dy != 0:
        return [dx, dy]

    if 0 <= x + 1 < grid_width:
        return [1, 0]
    if 0 <= x - 1 < grid_width:
        return [-1, 0]
    if 0 <= y + 1 < grid_height:
        return [0, 1]
    if 0 <= y - 1 < grid_height:
        return [0, -1]

    return [0, 0]
